package com.mfg.erp.controller;import com.mfg.common.api.*;import com.mfg.common.exception.BizException;import com.mfg.erp.entity.FinancialVoucher;import com.mfg.erp.repo.FinancialVoucherRepository;import com.mfg.security.config.CurrentUser;import lombok.RequiredArgsConstructor;import org.springframework.data.domain.*;import org.springframework.web.bind.annotation.*;import java.math.*;import java.time.*;
@RestController @RequestMapping("/api/erp/financial-vouchers") @RequiredArgsConstructor public class FinancialVoucherController{private final FinancialVoucherRepository repo;@GetMapping public ApiResponse<Page<FinancialVoucher>> page(@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="20")int size){return ApiResponse.ok(repo.findAll(PageRequest.of(Math.max(0,page-1),Math.min(size,200))));}@PostMapping public ApiResponse<FinancialVoucher> create(@RequestBody FinancialVoucher v){if(repo.existsByVoucherNoAndCompanyCodeAndFiscalPeriod(v.getVoucherNo(),v.getCompanyCode(),v.getFiscalPeriod()))throw BizException.of(ErrorCode.MASTER_DATA_ALREADY_EXISTS,"会计期间内凭证号重复");if(v.getDebitAmount()==null||v.getCreditAmount()==null||v.getDebitAmount().compareTo(v.getCreditAmount())!=0)throw BizException.of(ErrorCode.MASTER_DATA_INVALID_STATE,"借方金额必须等于贷方金额");v.setVoucherDate(v.getVoucherDate()==null?LocalDate.now():v.getVoucherDate());v.setCreatedBy(CurrentUser.usernameOrSystem());return ApiResponse.ok(repo.save(v));}}
